check('Fresh accounts start with the first of three introduction slides',()=>{assert.match(html(),/Get started<br>in minutes/);assert.equal(snapshot().onboardingCompleted,false);assert.equal(snapshot().balance,0);assert.equal(snapshot().cards.length,0);assert.ok(doc.body.classList.contains('onboarding-mode'));go('onboarding/2');assert.match(html(),/Top up<br>your wallet/);go('onboarding/3');assert.match(html(),/Spend your crypto<br>in dollars/);assert.doesNotMatch(html(),/plan-fees/)});
