check('One-time reveal shows exactly twelve numbered example words and saves only progress',()=>{const before=snapshot();submit('recovery-reveal',{understood:'on'});assert.match(html(),/recovery-word-grid/);const grid=html().split('<ol class="recovery-word-grid">')[1].split('</ol>')[0];assert.equal((grid.match(/<li>/g)||[]).length,12);for(const word of ['demo','maple','velvet','orbit','canyon','silver','meadow','cedar','harbor','lunar','pebble','sunrise'])assert.ok(grid.includes('>'+word+'<'));assert.match(html(),/Example phrase · demo only/);assert.match(html(),/example phrase cannot recover an account/);assert.equal(query('#recovery-confirm-button').disabled,true);assert.ok(snapshot().recovery.revealedAt);assert.equal(snapshot().recovery.confirmedAt,null);assert.deepEqual(snapshot().wallets,before.wallets);assert.deepEqual(snapshot().cards,before.cards);assert.deepEqual(snapshot().transactions,before.transactions);assert.deepEqual(Object.keys(snapshot().recovery).sort(),['confirmedAt','revealedAt']);const saved=JSON.parse(storage.get('whoo-card-mobile-v2'));assert.doesNotMatch(JSON.stringify(saved),/demo maple|"words"|"phrase"|"seed"/);const revealed=html(),revealedState=snapshot();submit('recovery-reveal',{understood:'on'});assert.equal(html(),revealed);assert.deepEqual(snapshot(),revealedState);submit('recovery-confirm',{});assert.match(query('#form-error').textContent,/saved all 12 words/);assert.equal(snapshot().recovery.confirmedAt,null)});
