check('Home totals wallet estimates and every card without changing the wallet-only total',()=>{go('home');const before=snapshot(),total=before.balance+before.cards.reduce((n,c)=>n+c.balance,0),amount=html().match(/<div class="home-total-amount">([\s\S]*?)<\/div>/)[1].replace(/<[^>]*>/g,'').replace(/,/g,'');assert.equal(Number(amount.replace('$','')),total/100);assert.equal(queryAll('.home-stack-item').length,before.wallets.length+before.cards.length);assert.deepEqual(snapshot(),before);go('wallet');const walletAmount=html().match(/<div class="wallet-total-value">([\s\S]*?)<\/div>/)[1].replace(/<[^>]*>/g,'').replace(/,/g,'');assert.equal(Number(walletAmount.replace('$','')),before.balance/100)});
check('Touch hold peeks a balance, suppresses its release click and closes the peek',()=>{freshHome();const before=snapshot(),row=queryAll('.home-stack-item')[0];pointer(row,'pointerdown');advance(329);assert.ok(!row.classList.contains('balance-peek'));advance(1);assert.ok(row.classList.contains('balance-peek'));pointer(row,'pointerup');let stopped=false;row.dispatchEvent({type:'click',stopPropagation(){stopped=true}});assert.equal(stopped,true);assert.equal(roots['modal-root'].innerHTML,'');advance(1000);assert.ok(!row.classList.contains('balance-peek'));assert.deepEqual(snapshot(),before)});
