check('Replacement requires confirmation, is idempotent and moves no money',()=>{go('home');const before=snapshot();action('home-card',{id:plusId});action('quick-replace-card',{id:plusId});assert.match(roots['modal-root'].innerHTML,/Request demo replacement/);assert.deepEqual(snapshot(),before);action('return-quick-card',{id:plusId});assert.deepEqual(snapshot(),before);action('quick-replace-card',{id:plusId});action('confirm-card-replacement',{id:plusId});const after=snapshot();assert.deepEqual(after.wallets,before.wallets);assert.deepEqual(after.cards.map(c=>[c.id,c.balance,c.status]),before.cards.map(c=>[c.id,c.balance,c.status]));assert.equal(after.transactions.length,before.transactions.length+1);assert.equal(after.transactions[0].amount,0);assert.equal(after.transactions[0].status,'pending');assert.equal(after.cards.find(c=>c.id===plusId).replacementPending,true);assert.match(roots['modal-root'].innerHTML,/Requested/);action('confirm-card-replacement',{id:plusId});assert.deepEqual(snapshot(),after);action('close-modal');assert.match(html(),/Card replacement requested/);assert.doesNotMatch(html(),/−\$0\.00/);reload(before,'#/home')});
