check('A dismissed Home alert stays dismissed through refresh until the next sign-in',()=>{const before=snapshot(),sessionKey='whoo-card-mobile-v2-home-session';session.clear();storage.delete('whoo-card-mobile-v2-home-alert');const demo=JSON.parse(JSON.stringify(before));demo.recovery={revealedAt:null,confirmedAt:null};reload(demo,'#/home');assert.match(html(),/aria-label="Account reminder"/);const first=JSON.parse(session.get(sessionKey)).alertId;action('dismiss-home-alert');assert.doesNotMatch(html(),/aria-label="Account reminder"/);go('wallet');go('home');assert.doesNotMatch(html(),/aria-label="Account reminder"/);reload(demo,'#/home');assert.doesNotMatch(html(),/aria-label="Account reminder"/);go('login');action('auth-method',{method:'email'});submit('auth',{contact:demo.user.email||'alex@example.com'});submit('verify',{digit0:'1',digit1:'2',digit2:'3',digit3:'4',digit4:'5',digit5:'6'});assert.equal(location.hash,'#/home');assert.match(html(),/aria-label="Account reminder"/);assert.notEqual(JSON.parse(session.get(sessionKey)).alertId,first);reload(before,'#/home')});
check('Setup is one dismissible stage and recovery lives in Resources until promoted',()=>{const before=snapshot(),fresh=JSON.parse(JSON.stringify(before));fresh.cards=[];fresh.recovery={revealedAt:null,confirmedAt:null};session.clear();storage.delete('whoo-card-mobile-v2-home-alert');reload(fresh,'#/home');assert.match(html(),/Choose your first card/);assert.equal((html().match(/aria-label="Account reminder"/g)||[]).length,1);assert.doesNotMatch(html(),/setup-checklist|setup-number/);assert.match(html(),/data-action="resource-recovery"/);action('dismiss-home-alert');go('login');action('auth-method',{method:'email'});submit('auth',{contact:fresh.user.email||'alex@example.com'});submit('verify',{digit0:'1',digit1:'2',digit2:'3',digit3:'4',digit4:'5',digit5:'6'});go('home');assert.match(html(),/Secure Your Account/);assert.doesNotMatch(html(),/data-action="resource-recovery"/);action('dismiss-home-alert');assert.match(html(),/data-action="resource-recovery"/);reload(before,'#/home')});
check('News and Insights shares eligible campaigns with the top image banner',()=>{freshHome();const h=html();for(const kind of ['support','ledger','staking','exchange','controls','bills'])assert.equal(((h.split('class="home-resources"')[1]||'').match(new RegExp('data-action="resource-'+kind+'"','g'))||[]).length+(h.includes('data-campaign="'+kind+'"')?1:0),1);assert.match(h,/resource-square/);assert.match(h,/resource-wide/);assert.match(h,/24\/7 help/);assert.match(h,/Staking · annual rate preview/);assert.doesNotMatch(h,/16% per month|reward/i);assert.ok(h.indexOf('home-resources')>h.indexOf('Recent activity'));assert.match(h,/resource-previous/);assert.match(h,/resource-next/)});
check('Resource arrows and keyboard reach both ends, and mouse grab suppresses release activation',()=>{let rail=freshHome(),before=snapshot();assert.equal(query('#resource-previous').disabled,true);query('#resource-next').dispatchEvent({type:'click'});assert.ok(rail.scrollLeft>0);assert.equal(query('#resource-previous').disabled,false);rail.dispatchEvent({type:'keydown',key:'End'});assert.equal(rail.scrollLeft,rail.scrollWidth-rail.clientWidth);assert.equal(query('#resource-next').disabled,true);rail.dispatchEvent({type:'keydown',key:'Home'});assert.equal(rail.scrollLeft,0);pointer(rail,'pointerdown',250,100,'mouse');pointer(rail,'pointermove',70,103,'mouse');assert.ok(rail.classList.contains('is-dragging'));assert.equal(rail.scrollLeft,180);pointer(rail,'pointerup',70,103,'mouse');assert.ok(!rail.classList.contains('is-dragging'));assert.ok(rail.scrollLeft>0);const tile=queryAll('.resource-tile')[0];let blocked=false;rail.dispatchEvent({type:'click',target:tile,preventDefault(){blocked=true}});assert.equal(blocked,true);assert.equal(roots['modal-root'].innerHTML,'');assert.deepEqual(snapshot(),before)});
check('Resource tour waits for visibility, shows every tile, returns to default and does not loop',()=>{const rail=freshHome(),before=snapshot();advance(10000);assert.equal(rail.scrollLeft,0);resourceVisible();advance(1800);assert.ok(rail.scrollLeft>0);advance(20000);assert.equal(rail.scrollLeft,0);const stops=[...rail.scrollHistory];assert.ok(stops.includes(rail.scrollWidth-rail.clientWidth));for(const tile of queryAll('.resource-tile'))assert.ok(stops.some(x=>tile.offsetLeft>=x-1&&tile.offsetLeft+tile.offsetWidth<=x+rail.clientWidth+1));advance(30000);assert.deepEqual(rail.scrollHistory,stops);resourceVisible();advance(10000);assert.deepEqual(rail.scrollHistory,stops);assert.deepEqual(snapshot(),before)});
check('Horizontal touch and wheel gestures, keyboard focus and arrow use stop the automatic resource tour',()=>{for(const kind of ['touch','wheel','focusin','arrow']){const rail=freshHome();resourceVisible();advance(1800);const at=rail.scrollLeft;if(kind==='touch'){const e=pointer(rail,'pointerdown',200,100);assert.ok(!e.prevented);pointer(rail,'pointermove',100,103);pointer(rail,'pointerup',100,103)}else if(kind==='arrow')query('#resource-previous').dispatchEvent({type:'click'});else rail.dispatchEvent({type:kind,deltaX:80,deltaY:0});const after=rail.scrollLeft;advance(20000);assert.equal(rail.scrollLeft,after,kind);if(kind!=='arrow')assert.equal(after,at)}});
check('The resource tour works with reduced motion, pauses on hidden pages and cleans up on navigation',()=>{reducedMotion=true;let rail=freshHome();resourceVisible();advance(20000);assert.equal(rail.scrollLeft,0);assert.ok(rail.scrollHistory.some(x=>x>0));reducedMotion=false;rail=freshHome();resourceVisible();advance(1800);doc.visibilityState='hidden';for(const fn of listeners.visibilitychange||[])fn();const at=rail.scrollLeft;advance(20000);assert.equal(rail.scrollLeft,at);doc.visibilityState='visible';rail=freshHome();resourceVisible();advance(1800);const old=rail,was=rail.scrollLeft;go('wallet');advance(20000);assert.equal(old.scrollLeft,was);assert.equal((old.events.pointermove||[]).length,0);assert.equal((listeners.visibilitychange||[]).length,0)});
check('Informational future feature tiles and support cannot move any money',()=>{go('home');for(const kind of ['ledger','staking','controls','bills','support']){const before=snapshot();action('resource-'+kind);const h=roots['modal-root'].innerHTML;assert.match(h,/role="dialog"/);if(kind==='staking'){assert.match(h,/illustrative annual rate/);assert.match(h,/not a monthly or guaranteed return/);assert.match(h,/Staking is not active/)}if(kind==='bills')assert.match(h,/future update/);if(kind==='controls')assert.match(h,/approval rules are planned/);assert.deepEqual(snapshot(),before);action('close-modal')}const before=snapshot();action('resource-exchange');assert.match(roots['modal-root'].innerHTML,/Top up your/);assert.deepEqual(snapshot(),before);action('close-modal')});

check('Home stack headers use one line, real logo images and a small Add wallet control',()=>{go('home');const h=html();const rows=[...h.matchAll(/<button class="home-stack-item[\s\S]*?<\/button>/g)].map(m=>m[0]);assert.equal(rows.length,snapshot().wallets.length+snapshot().cards.length);for(const row of rows){assert.doesNotMatch(row,/<small>|<br\b/);assert.equal((row.match(/class="stack-label"/g)||[]).length,row.includes('home-stack-wallet')?1:0);assert.equal((row.match(/class="stack-drop-arrow"/g)||[]).length,1)}assert.doesNotMatch(h,/Hold for balance|Hover for balance|stack-peek-hint/);assert.match(h,/class="stack-add-wallet" data-action="add-wallet"/);assert.equal((h.match(/data-action="add-wallet"/g)||[]).length,2);assert.match(h,/class="crypto-symbol-image"/);assert.doesNotMatch(h,/>₮</);assert.doesNotMatch(h,/stack-card-mark/)});
