check('The wallet Receive view matches the QR, network and full-width copy hierarchy',()=>{go('home');const before=snapshot();action('home-wallet',{id:usdt});const h=roots['modal-root'].innerHTML;for(const value of ['Receive USDT','quick-wallet-tabs','wallet-receive-panel','wallet-large-qr','Network','Available','wallet-address-copy','Copy demo receiving address'])assert.ok(h.includes(value),value);assert.match(h,/Tether/);assert.doesNotMatch(h,/wallet-tether-wordmark/);assert.match(h,/data-value="DEMO_USDT_TRC20_NOT_A_PAYMENT_ADDRESS"/);assert.doesNotMatch(h,/quick-wallet-hero|quick-wallet-receiving|Tap wallet for full details/);assert.deepEqual(snapshot(),before);action('close-modal')});
check('Wallet Send uses the selected native wallet, reviews without debiting and switches back to Receive',()=>{go('home');const before=snapshot();action('home-wallet',{id:btc});action('quick-wallet-mode',{id:btc,mode:'send'});assert.match(roots['modal-root'].innerHTML,/Send BTC/);assert.match(roots['modal-root'].innerHTML,/data-form="withdraw"/);assert.equal(query('#source-wallet').value,btc);submit('withdraw',{walletId:btc,amount:'0',address:'DEMO_DESTINATION_ADDRESS'});assert.deepEqual(snapshot(),before);assert.match(query('#form-error').textContent,/valid|positive|amount/i);action('quick-wallet-mode',{id:btc,mode:'receive'});assert.match(roots['modal-root'].innerHTML,/wallet-large-qr/);assert.doesNotMatch(roots['modal-root'].innerHTML,/data-form="withdraw"/);action('quick-wallet-mode',{id:btc,mode:'send'});submit('withdraw',{walletId:btc,amount:'0.001',address:'DEMO_DESTINATION_ADDRESS'});assert.equal(location.hash,'#/withdraw/review');assert.match(html(),/0\.001 BTC/);assert.deepEqual(snapshot(),before);go('home')});
check('Both quick views have one bounded scroll region and their centre handle closes the sheet',()=>{go('home');const before=snapshot();for(const [kind,id]of [['wallet',btc],['card',plusId]]){action('home-'+kind,{id});const h=roots['modal-root'].innerHTML;assert.equal((h.match(/class="quick-sheet-scroll"/g)||[]).length,1);const header=h.indexOf('class="quick-sheet-header"'),body=h.indexOf('class="quick-sheet-scroll"');assert.ok(header>=0&&header<body);const tag=h.match(/<button class="sheet-grab"[^>]*>/)[0],handle=new Node(tag);assert.equal(handle.dataset.action,'close-modal');handle.dispatchEvent({type:'click'});assert.equal(roots['modal-root'].innerHTML,'');assert.equal(roots['app-shell'].inert,false);assert.equal(roots['bottom-nav'].inert,false)}assert.deepEqual(snapshot(),before)});
check('Card quick access uses a full-width art region and the compact reference field groups',()=>{go('home');action('home-card',{id:plusId});const h=roots['modal-root'].innerHTML;assert.match(h,/quick-card-hero/);assert.match(h,/card-reference-art/);assert.match(h,/>Reveal details</);assert.match(h,/quick-card-small-details/);assert.match(h,/quick-billing-wrap/);assert.match(h,/Copy sample billing address/);assert.doesNotMatch(h,/Tap card for full details|quick-open-hint/);const billing=h.split('class="quick-billing-wrap"')[1].split('class="quick-card-actions"')[0];assert.ok(billing.indexOf('</details>')<billing.indexOf('aria-label="Copy sample billing address"'));action('close-modal')});
check('Copying from the large wallet address bar retains the complete demo address',()=>{go('home');action('home-wallet',{id:btc});const h=roots['modal-root'].innerHTML,tag=h.match(/<button class="wallet-address-copy"[^>]*>/)[0],button=new Node(tag),writes=[],previous=context.navigator.clipboard.writeText;try{context.navigator.clipboard.writeText=async value=>writes.push(value);button.dispatchEvent({type:'click'});assert.deepEqual(writes,['DEMO_BTC_BTC_NOT_A_PAYMENT_ADDRESS'])}finally{context.navigator.clipboard.writeText=previous}action('close-modal')});
check('Campaigns exchange top and tile positions with the same image and never duplicate the promoted item',()=>{const original=snapshot(),oldSession=new Map(session),demo=JSON.parse(JSON.stringify(original)),key='whoo-card-mobile-v2-home-session';demo.cards[0].status='selected';demo.cards[0].balance=0;demo.recovery={revealedAt:null,confirmedAt:null};for(const id of ['setup','recovery','ledger','controls','exchange','staking','bills','support']){session.set(key,JSON.stringify({id:'session-'+id,alertId:id,dismissed:false}));reload(demo,'#/home');const h=html();assert.match(h,new RegExp('data-campaign="'+id+'"'));assert.doesNotMatch(h.split('class="home-resources"')[1],new RegExp('data-action="resource-'+id+'"'));const banner=h.match(/<aside class="home-alert[\s\S]*?<\/aside>/)[0],image=banner.match(/class="home-alert-image" src="([^"]+)"/)[1];action('dismiss-home-alert');const tile=html().match(new RegExp('<button class="resource-tile[^>]+data-action="resource-'+id+'"[\\s\\S]*?<\\/button>'))[0];assert.ok(tile.includes('src="'+image+'"'),id);assert.deepEqual(snapshot(),demo)}session.clear();for(const [k,v]of oldSession)session.set(k,v);reload(original,'#/home')});
