const routes=['onboarding/1','onboarding/2','onboarding/3','home','wallet',...snapshot().wallets.map(w=>'wallet/'+w.id),'cards','discover/plus','discover/premium','discover/metal','design/midnight','create/premium','card/'+plusId,'fund/'+plusId,'fund/success/'+plusId,'deposit','deposit/'+btc,'deposit/method','deposit/payment/'+depId,'deposit-logs','withdraw','withdraw/'+eth,'withdraw/review','activity','activity/cards','activity/deposits','activity/withdrawals','referrals','profile','profile/edit','profile/recovery','security','preferences','signup','login','verify','signup?ref=WHOOJ8'];
check('Every route and modal renders with existing local assets',()=>{for(const route of routes){go(route);assert.ok(html().length>100,route);assert.doesNotMatch(html(),/This preview page could not be found|src="undefined"/,route);for(const m of (html()+roots['modal-root'].innerHTML).matchAll(/(?:src|href)="(assets\/[^\"]+)"/g))assert.ok(fs.existsSync(path.join(staticRoot,m[1])),m[1])}});
check('The app remains phone-width with no real network calls or API secrets',()=>{const page=fs.readFileSync(path.join(staticRoot,'index.html'),'utf8');const css=fs.readFileSync(path.join(staticRoot,'styles.css'),'utf8');assert.doesNotMatch(page,/<aside|id="sidebar"/);assert.match(css,/max-width:430px/);assert.doesNotMatch(source,/\bfetch\s*\(|XMLHttpRequest|WebSocket/)});
function reload(saved,hash=''){timers.clear();observers.length=0;storage.set('whoo-card-mobile-v2',JSON.stringify(saved));for(const key of Object.keys(listeners))delete listeners[key];for(const key of Object.keys(winListeners))delete winListeners[key];location._hash=hash;cache.clear();vm.runInNewContext(source,context,{filename:'app.js'});app=window.WhooPreview;}
check('Saved native wallet quantities survive reload and the review URL opens the intro',()=>{const before=snapshot();reload(before);assert.deepEqual(snapshot(),before);assert.match(html(),/Get started<br>in minutes/);assert.ok(doc.body.classList.contains('onboarding-mode'))});
check('Legacy USD balances migrate once to USDT while preserving cards and activity',()=>{const saved=snapshot();saved.version=2;saved.balance=12345;delete saved.wallets;for(const c of saved.cards)c.plan=({plus:'disposable',premium:'standard',metal:'platinum'})[c.plan];const originalCards=saved.cards.map(c=>[c.id,c.balance,c.status]);const pending={id:'legacy-pending',type:'deposit',asset:'USDC',network:'ERC20',amount:5000,status:'awaiting_payment',date:new Date().toISOString(),title:'USDC deposit',subtitle:'Ethereum'};saved.transactions.unshift(pending);reload(saved,'#/wallet');assert.equal(snapshot().version,3);assert.equal(walletBalance(usdt),'123450000');assert.equal(snapshot().balance,12345);assert.deepEqual(snapshot().cards.map(c=>[c.id,c.balance,c.status]),originalCards);assert.equal(snapshot().transactions.length,saved.transactions.length);assert.equal(snapshot().onboardingCompleted,true);const migrated=snapshot();reload(migrated,'#/wallet');assert.equal(walletBalance(usdt),'123450000');action('confirm-deposit',{id:'legacy-pending'});assert.equal(walletBalance(usdc),'50000000');assert.equal(snapshot().balance,17345);action('confirm-deposit',{id:'legacy-pending'});assert.equal(snapshot().balance,17345)});
check('Wallet total is recalculated from assets instead of trusting a stale USD cache',()=>{const saved=snapshot();saved.balance=1;reload(saved,'#/wallet');assert.equal(snapshot().balance,17345);assert.match(html(),/173/)});
check('Reset clears all financial state and returns to intro slide one',()=>{action('do-reset');assert.equal(snapshot().balance,0);assert.equal(snapshot().cards.length,0);assert.equal(snapshot().wallets.length,1);assert.equal(snapshot().wallets[0].balanceAtomic,'0');assert.equal(snapshot().transactions.length,0);assert.deepEqual(snapshot().recovery,{revealedAt:null,confirmedAt:null});assert.equal(snapshot().onboardingCompleted,false);assert.equal(location.hash,'#/onboarding/1')});
if(process.env.WHOO_CHECK_REPORT!=='0')fs.writeFileSync(path.join(project,'VALIDATION.json'),JSON.stringify({passed:checks.length,routeStates:routes.length,checks,limitations:'Event/data harness and static asset checks. Full browser visual QA unavailable. Exchange quotes are illustrative; no provider calls.'},null,2));
console.log(`Verified ${checks.length} checks and ${routes.length} route states.`);
